[{"order":1,"type":"heading","text":"React Native: Navigation with React Navigation"},{"order":2,"type":"paragraph","text":"Navigation is a crucial aspect of any mobile application. React Navigation is a popular and powerful library for handling navigation in React Native applications. This tutorial will guide you through the process of setting up and using React Navigation to create a seamless navigation experience."},{"order":3,"type":"heading","text":"Prerequisites"},{"order":4,"type":"bullet_point","text":"Node.js and npm or yarn installed"},{"order":5,"type":"bullet_point","text":"React Native development environment set up (e.g., Expo or React Native CLI)"},{"order":6,"type":"bullet_point","text":"Basic understanding of React Native components and concepts"},{"order":7,"type":"heading","text":"Setting Up a New React Native Project"},{"order":8,"type":"paragraph","text":"If you don't have an existing React Native project, create a new one using either Expo or React Native CLI."},{"order":9,"type":"subheading","text":"Using Expo"},{"order":10,"type":"code","text":"expo init MyNavigationApp
cd MyNavigationApp"},{"order":11,"type":"subheading","text":"Using React Native CLI"},{"order":12,"type":"code","text":"npx react-native init MyNavigationApp
cd MyNavigationApp"},{"order":13,"type":"heading","text":"Installing React Navigation"},{"order":14,"type":"paragraph","text":"Install the core React Navigation library and the necessary navigators (e.g., stack, tab, drawer)."},{"order":15,"type":"code","text":"npm install @react-navigation/native @react-navigation/stack
# or
yarn add @react-navigation/native @react-navigation/stack"},{"order":16,"type":"paragraph","text":"Also, install the required dependencies for React Navigation."},{"order":17,"type":"code","text":"npx expo install react-native-gesture-handler react-native-reanimated react-native-screens react-native-safe-area-context @react-native-community/masked-view"},{"order":18,"type":"heading","text":"Creating a Stack Navigator"},{"order":19,"type":"paragraph","text":"A stack navigator provides a way for your app to transition between screens, where each new screen is placed on top of a stack."},{"order":20,"type":"paragraph","text":"Create a new file, for example, `AppNavigator.js`, to define your navigator."},{"order":21,"type":"code","text":"// AppNavigator.js
import * as React from 'react';
import { NavigationContainer } from '@react-navigation/native';
import { createStackNavigator } from '@react-navigation/stack';
import HomeScreen from './screens/HomeScreen';
import DetailsScreen from './screens/DetailsScreen';

const Stack = createStackNavigator();

function AppNavigator() {
  return (
    <NavigationContainer>
      <Stack.Navigator initialRouteName="Home">
        <Stack.Screen name="Home" component={HomeScreen} />
        <Stack.Screen name="Details" component={DetailsScreen} />
      </Stack.Navigator>
    </NavigationContainer>
  );
}

export default AppNavigator;"},{"order":22,"type":"paragraph","text":"In this example, we've created a stack navigator with two screens: `Home` and `Details`.  We also need to create the `HomeScreen.js` and `DetailsScreen.js` files."},{"order":23,"type":"code","text":"// screens/HomeScreen.js
import React from 'react';
import { View, Text, Button } from 'react-native';

function HomeScreen({ navigation }) {
  return (
    <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}>
      <Text>Home Screen</Text>
      <Button
        title="Go to Details"
        onPress={() => navigation.navigate('Details', {itemId: 86, otherParam: 'anything you want here'})}
      />
    </View>
  );
}

export default HomeScreen;"},{"order":24,"type":"code","text":"// screens/DetailsScreen.js
import React from 'react';
import { View, Text, Button } from 'react-native';

function DetailsScreen({ route, navigation }) {
  const { itemId, otherParam } = route.params;
  return (
    <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}>
      <Text>Details Screen</Text>
      <Text>itemId: {JSON.stringify(itemId)}</Text>
      <Text>otherParam: {JSON.stringify(otherParam)}</Text>
      <Button title="Go to Home" onPress={() => navigation.navigate('Home')} />
      <Button title="Go back" onPress={() => navigation.goBack()} />
    </View>
  );
}

export default DetailsScreen;"},{"order":25,"type":"paragraph","text":"Now, integrate the `AppNavigator` into your main `App.js` file."},{"order":26,"type":"code","text":"// App.js
import React from 'react';
import AppNavigator from './AppNavigator';

function App() {
  return (
    <AppNavigator />
  );
}

export default App;"},{"order":27,"type":"heading","text":"Running Your Application"},{"order":28,"type":"paragraph","text":"Start your React Native application using either Expo or React Native CLI."},{"order":29,"type":"code","text":"# Using Expo
npm start

# Using React Native CLI
npx react-native run-android # or npx react-native run-ios"},{"order":30,"type":"heading","text":"Passing Parameters to Routes"},{"order":31,"type":"paragraph","text":"You can pass parameters to routes using the `navigation.navigate` function. The second argument is an object containing the parameters."},{"order":32,"type":"code","text":"navigation.navigate('Details', { itemId: 86, otherParam: 'First Param' });"},{"order":33,"type":"paragraph","text":"In the destination screen, you can access the parameters using `route.params`."},{"order":34,"type":"code","text":"const { itemId, otherParam } = route.params;"},{"order":35,"type":"heading","text":"Customizing the Header"},{"order":36,"type":"paragraph","text":"React Navigation allows you to customize the header of each screen."},{"order":37,"type":"code","text":"<Stack.Screen
  name="Details"
  component={DetailsScreen}
  options={{ title: 'Details Screen', headerStyle: { backgroundColor: '#f4511e' }, headerTintColor: '#fff' }}
/>"},{"order":38,"type":"paragraph","text":"You can also customize the header within the component itself using `navigation.setOptions`."},{"order":39,"type":"code","text":"React.useLayoutEffect(() => {
    navigation.setOptions({
      headerRight: () => (
        <Button
          onPress={() => alert('This is a button!')}
          title="Info"
          color="#fff"
        />
      ),
    });
  }, [navigation]);"},{"order":40,"type":"heading","text":"Tab Navigation"},{"order":41,"type":"paragraph","text":"Tab navigation allows users to switch between different sections of your app using tabs."},{"order":42,"type":"code","text":"npm install @react-navigation/bottom-tabs
# or
yarn add @react-navigation/bottom-tabs"},{"order":43,"type":"code","text":"// TabNavigator.js
import * as React from 'react';
import { createBottomTabNavigator } from '@react-navigation/bottom-tabs';
import HomeScreen from './screens/HomeScreen';
import SettingsScreen from './screens/SettingsScreen';

const Tab = createBottomTabNavigator();

function TabNavigator() {
  return (
    <Tab.Navigator>
      <Tab.Screen name="Home" component={HomeScreen} />
      <Tab.Screen name="Settings" component={SettingsScreen} />
    </Tab.Navigator>
  );
}

export default TabNavigator;"},{"order":44,"type":"paragraph","text":"Don't forget to create a `SettingsScreen.js` file."},{"order":45,"type":"code","text":"// screens/SettingsScreen.js
import React from 'react';
import { View, Text } from 'react-native';

function SettingsScreen() {
  return (
    <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}>
      <Text>Settings Screen</Text>
    </View>
  );
}

export default SettingsScreen;"},{"order":46,"type":"paragraph","text":"Replace `AppNavigator` in `App.js` with `TabNavigator`."},{"order":47,"type":"code","text":"// App.js
import React from 'react';
import TabNavigator from './TabNavigator';

function App() {
  return (
    <TabNavigator />
  );
}

export default App;"},{"order":48,"type":"heading","text":"Drawer Navigation"},{"order":49,"type":"paragraph","text":"Drawer navigation provides a sidebar menu for navigating between screens."},{"order":50,"type":"code","text":"npm install @react-navigation/drawer
# or
yarn add @react-navigation/drawer"},{"order":51,"type":"code","text":"// DrawerNavigator.js
import * as React from 'react';
import { createDrawerNavigator } from '@react-navigation/drawer';
import HomeScreen from './screens/HomeScreen';
import SettingsScreen from './screens/SettingsScreen';

const Drawer = createDrawerNavigator();

function DrawerNavigator() {
  return (
    <Drawer.Navigator initialRouteName="Home">
      <Drawer.Screen name="Home" component={HomeScreen} />
      <Drawer.Screen name="Settings" component={SettingsScreen} />
    </Drawer.Navigator>
  );
}

export default DrawerNavigator;"},{"order":52,"type":"paragraph","text":"Replace `AppNavigator` or `TabNavigator` in `App.js` with `DrawerNavigator`."},{"order":53,"type":"code","text":"// App.js
import React from 'react';
import DrawerNavigator from './DrawerNavigator';

function App() {
  return (
    <DrawerNavigator />
  );
}

export default App;"},{"order":54,"type":"heading","text":"Conclusion"},{"order":55,"type":"paragraph","text":"React Navigation is a versatile library for handling navigation in React Native applications. This tutorial covered the basics of setting up and using stack, tab, and drawer navigators. You can further explore the library's documentation to discover more advanced features and customization options."}]
